create extension if not exists pgcrypto;
create schema if not exists private;
create type public.company_role as enum ('owner','admin','member');
create type public.client_type as enum ('person','business');
create type public.quotation_status as enum ('draft','sent','follow_up','accepted','rejected','expired');
create table public.companies (id uuid primary key default gen_random_uuid(),commercial_name text not null check(char_length(trim(commercial_name)) between 2 and 160),legal_name text,tax_id text,address text,phone text,email text,logo_path text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.company_users (company_id uuid not null references public.companies(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,role public.company_role not null default 'member',created_at timestamptz not null default now(),primary key(company_id,user_id));
create table public.company_settings (company_id uuid primary key references public.companies(id) on delete cascade,currency_code char(3) not null default 'CLP',timezone text not null default 'America/Santiago',default_tax_rate numeric(5,2) not null default 19 check(default_tax_rate between 0 and 100),quotation_prefix text not null default 'COT',terms text,updated_at timestamptz not null default now());
create table public.clients (id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,name text not null check(char_length(trim(name)) between 2 and 180),tax_id text,phone text,email text,address text,client_type public.client_type not null default 'person',notes text,archived_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(company_id,tax_id));
create table public.quotations (id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,client_id uuid not null references public.clients(id) on delete restrict,number integer not null check(number > 0),issued_on date not null default current_date,valid_until date,description text,status public.quotation_status not null default 'draft',discount_total numeric(14,2) not null default 0 check(discount_total >= 0),tax_rate numeric(5,2) not null default 19 check(tax_rate between 0 and 100),subtotal numeric(14,2) not null default 0 check(subtotal >= 0),tax_total numeric(14,2) not null default 0 check(tax_total >= 0),total numeric(14,2) not null default 0 check(total >= 0),notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(company_id,number));
create table public.quotation_items (id uuid primary key default gen_random_uuid(),quotation_id uuid not null references public.quotations(id) on delete cascade,position smallint not null check(position > 0),description text not null,quantity numeric(12,2) not null check(quantity > 0),unit_price numeric(14,2) not null check(unit_price >= 0),discount_rate numeric(5,2) not null default 0 check(discount_rate between 0 and 100),total numeric(14,2) not null check(total >= 0),unique(quotation_id,position));
create table public.quotation_followups (id uuid primary key default gen_random_uuid(),quotation_id uuid not null references public.quotations(id) on delete cascade,contacted_at timestamptz,next_followup_at timestamptz,result text,notes text not null default '',created_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index clients_company_search_idx on public.clients(company_id,name) where archived_at is null;
create index quotations_company_status_idx on public.quotations(company_id,status);
create index followups_pending_idx on public.quotation_followups(next_followup_at) where next_followup_at is not null;
create or replace function private.is_company_member(target_company_id uuid) returns boolean language sql stable security definer set search_path = '' as $$ select exists(select 1 from public.company_users where company_id=target_company_id and user_id=(select auth.uid())); $$;
revoke all on function private.is_company_member(uuid) from public;
grant usage on schema private to authenticated;
grant execute on function private.is_company_member(uuid) to authenticated;
alter table public.companies enable row level security; alter table public.company_users enable row level security; alter table public.company_settings enable row level security; alter table public.clients enable row level security; alter table public.quotations enable row level security; alter table public.quotation_items enable row level security; alter table public.quotation_followups enable row level security;
create policy "members read company" on public.companies for select to authenticated using ((select private.is_company_member(id)));
create policy "members read membership" on public.company_users for select to authenticated using ((select private.is_company_member(company_id)));
create policy "members access settings" on public.company_settings for all to authenticated using ((select private.is_company_member(company_id))) with check ((select private.is_company_member(company_id)));
create policy "members access clients" on public.clients for all to authenticated using ((select private.is_company_member(company_id))) with check ((select private.is_company_member(company_id)));
create policy "members access quotations" on public.quotations for all to authenticated using ((select private.is_company_member(company_id))) with check ((select private.is_company_member(company_id)));
create policy "members access items" on public.quotation_items for all to authenticated using (exists(select 1 from public.quotations q where q.id=quotation_id and private.is_company_member(q.company_id))) with check (exists(select 1 from public.quotations q where q.id=quotation_id and private.is_company_member(q.company_id)));
create policy "members access followups" on public.quotation_followups for all to authenticated using (exists(select 1 from public.quotations q where q.id=quotation_id and private.is_company_member(q.company_id))) with check (exists(select 1 from public.quotations q where q.id=quotation_id and private.is_company_member(q.company_id)));
